const tokens = new Map([["r1", { fam: 1, used: false }]]);
const revoked = new Set();
let n = 1;
function refresh(t) {
  const row = tokens.get(t);
  if (!row || revoked.has(row.fam)) return "401";
  if (row.used) {
    revoked.add(row.fam);
    return "401";
  }
  row.used = true;
  const next = "r" + ++n;
  tokens.set(next, { fam: row.fam, used: false });
  return next;
}
