const CAP = 3, RATE = 1; // tokens per second
let tokens = CAP, last = 0;

function allow(t) {
  tokens = Math.min(CAP, tokens + (t - last) * RATE);
  last = t;
  tokens -= 1;
  return tokens >= 0;
}

