const cache = new Map(); // keeps at most 2 entries
function get(key) {
  const value = cache.get(key);
  if (value !== undefined) {
    cache.delete(key);
    cache.set(key, value); // now the newest entry
  }
  return value;
}

function set(key, value) {
  cache.delete(key);
  cache.set(key, value);
  if (cache.size > 2) {
    cache.delete(cache.keys().next().value);
  }
}

